create table if not exists public.timeline_daw_normalization_render_jobs(id text primary key,owner_id uuid not null references auth.users(id) on delete cascade,session_id text not null,proof_id text not null references public.timeline_daw_normalization_proofs(id) on delete cascade,revision integer not null,song_id text not null,lane_id text not null references public.timeline_daw_private_audio_lanes(id) on delete cascade,state text not null check(state in('queued','rendering','completed','failed','cancelled')),progress double precision not null default 0 check(progress between 0 and 100),attempt integer not null default 1,source_id text not null,source_uri text not null,source_checksum text not null,recipe jsonb not null,artifact_id text,artifact_uri text,artifact_checksum text,failure_message text,cancel_requested boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(owner_id,session_id,revision,song_id));
alter table public.timeline_daw_normalization_render_jobs enable row level security;
create policy timeline_daw_normalization_render_jobs_owner on public.timeline_daw_normalization_render_jobs for all to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create index if not exists timeline_daw_normalization_render_jobs_revision on public.timeline_daw_normalization_render_jobs(owner_id,session_id,revision,state);
alter table public.timeline_daw_normalization_master_proofs add column if not exists render_job_ids jsonb not null default '[]'::jsonb;